      "content": "[build-system]\nrequires = [\"hatchling\"]\nbuild-backend = \"hatchling.build\"\n\n[project]\nname = \"memsearch\"\nversion = \"0.4.23\"\ndescription = \"Semantic memory search for markdown knowledge bases\"\nreadme = \"README.md\"\nlicense = \"MIT\"\nrequires-python = \">=3.10\"\nclassifiers = [\n    \"Programming Language :: Python :: 3.10\",\n    \"Programming Language :: Python :: 3.11\",\n    \"Programming Language :: Python :: 3.12\",\n    \"Programming Language :: Python :: 3.13\",\n]\ndependencies = [\n    \"pymilvus>=2.5.0,!=2.6.10; sys_platform != 'win32'\",\n    \"pymilvus>=2.6.11; sys_platform == 'win32'\",\n    \"milvus-lite>=2.5.0; sys_platform != 'win32'\",\n    \"milvus-lite>=3.1.1; sys_platform == 'win32'\",\n    \"click>=8.1\",\n    \"watchdog>=4.0\",\n    \"pathspec>=0.12\",\n    \"setuptools>=78.1.1,<81\",\n    \"tomli_w>=1.0\",\n    \"tomli>=2.0; python_version < '3.11'\",\n    \"openai>=1.0\",\n]\n\n[project.optional-dependencies]\ngoogle = [\"google-genai>=1.0\"]\nvoyage = [\"voyageai>=0.3\"]\njina = [\"httpx>=0.27\"]\nmistral = [\"mistralai>=1.0\"]\nollama = [\n    \"ollama>=0.4\",\n]\nlocal = [\n    \"einops>=0.8.2\",\n    \"sentence-transformers>=3.0\",\n]\nanthropic = [\"anthropic>=0.40\"]\nonnx = [\n    \"onnxruntime>=1.17,<1.24; python_version == '3.10'\",\n    \"onnxruntime>=1.17; python_version >= '3.11'\",\n    \"tokenizers>=0.15\",\n    \"huggingface-hub>=0.20\",\n]\nall = [\"memsearch[google,voyage,jina,mistral,ollama,local,anthropic,onnx]\"]\n\n[project.scripts]\nmemsearch = \"memsearch.cli:cli\"\n\n[tool.hatch.build.targets.wheel]\npackages = [\"src/memsearch\"]\n\n[tool.pytest.ini_options]\ntestpaths = [\"tests\"]\nasyncio_mode = \"auto\"\n\n[dependency-groups]\ndev = [\"pytest>=8.0\", \"pytest-asyncio>=0.24\", \"ruff>=0.9\", \"pytest-cov>=6.0\", \"pre-commit>=4.0\"]\ndocs = [\n    \"mkdocs>=1.6.1\",\n    \"mkdocs-material>=9.7.1\",\n    \"mkdocs-terminal>=4.8.0\",\n]\n\n[tool.ruff]\ntarget-version = \"py310\"\nline-length = 120\nsrc = [\"src\", \"tests\"]\n\n[tool.ruff.lint]\nselect = [\n    \"E\", \"W\",  # pycodestyle\n    \"F\",       # pyflakes\n    \"I\",       # isort\n    \"UP\",      # pyupgrade\n    \"B\",       # flake8-bugbear\n    \"C4\",      # flake8-comprehensions\n    \"SIM\",     # flake8-simplify\n    \"PIE\",     # flake8-pie\n    \"PGH\",     # pygrep-hooks\n    \"RUF\",     # ruff-specific\n    \"T20\",     # flake8-print\n    \"PERF\",    # perflint\n]\nignore = [\n    \"E501\",    # line length handled by formatter\n]\n\n[tool.ruff.lint.isort]\nknown-first-party = [\"memsearch\"]\n\n[tool.ruff.lint.per-file-ignores]\n\"tests/*\" = [\"T20\"]      # allow print in tests\n\"examples/*\" = [\"T20\"]   # allow print in examples\n\n[tool.coverage.run]\nsource = [\"memsearch\"]\n\n[tool.coverage.report]\nshow_missing = true\nskip_empty = true\n"
